<script setup>
import {computed,ref,nextTick,onBeforeUnmount,watch} from 'vue';
import PomodoroStartButton from './PomodoroStartButton.vue';
import CompletionMark from './CompletionMark.vue';
const props=defineProps({model:{type:Object,required:true},actions:{type:Object,required:true},chapter:{type:Object,required:true},taskId:{type:String,default:''}});
const dialog=ref(null),selectedId=ref(null),planView=ref(false),localError=ref(''),confirmFinish=ref(false),working=ref(false);
let opener=null,oldOverflow=null;
const rounds=computed(()=>props.model.rounds||[]);
const plans=computed(()=>props.model.plans||[]);
const selectedPlan=computed(()=>props.model.selectedPlan||plans.value.find(p=>p.id===props.model.selectedPlanId));
const selected=computed(()=>rounds.value.find(r=>r.id===selectedId.value));
const current=computed(()=>rounds.value.find(r=>!['finished','stopped'].includes(r.phase)));
const planRound=computed(()=>current.value?.planId===selectedPlan.value?.id?current.value:selectedPlan.value?.status==='completed'?rounds.value.filter(r=>r.planId===selectedPlan.value.id).at(-1):null);
const planEditable=computed(()=>planRound.value&&planRound.value.id===current.value?.id);
const editable=computed(()=>selected.value&&selected.value.id===current.value?.id);
const error=computed(()=>props.model.error||localError.value);
const questions=computed(()=>selected.value?.items.filter(i=>i.kind==='question')||[]);
const pending=computed(()=>questions.value.filter(i=>['submitted','pending'].includes(i.status)).length);
const time=ms=>{const sec=Math.floor(Math.max(0,ms||0)/1000);return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;};
const clock=r=>time(r.phase==='learning'?1500000-r.elapsedMs:r.phase==='break'?r.restMs:['finished','stopped'].includes(r.phase)?r.elapsedMs:0);
const phase=r=>r.phase==='learning'?(r.pausedAt!=null?'已暂停':'计时中'):({ready:'本轮计时完成',break:'休息中',finished:'已完成',stopped:'提前结束'}[r.phase]||'');
const status=i=>({read:'已阅读',graded:'已评分',submitted:'已提交',correct:'首次答对',incorrect:'需订正',corrected:'订正通过',pending:'待批改',answered:'已答疑'}[i.status]||'已记录');
const ringProgress=r=>r?Math.max(0,Math.min(100,r.phase==='break'?r.restMs/Math.max(1,r.restTotalMs)*100:(1500000-r.elapsedMs)/1500000*100)):100;
const progress=computed(()=>ringProgress(selected.value));
async function act(name,value){if(working.value)return false;localError.value='';working.value=true;try{await props.actions[name](value);confirmFinish.value=false;await nextTick();return !error.value;}catch(e){localError.value=e?.message||'操作失败，请重试。';return false;}finally{working.value=false;}}
function show(){if(!dialog.value||dialog.value.open)return;oldOverflow=document.body.style.overflow;document.body.style.overflow='hidden';dialog.value.showModal();}
async function open(round,event){if(!dialog.value?.open)opener=event.currentTarget;planView.value=false;selectedId.value=round.id;confirmFinish.value=false;await nextTick();if(selected.value)show();}
async function openPlan(plan,event){const button=event.currentTarget;if(!await act('pomodoroSelectPlan',plan.id))return;opener=button;planView.value=true;await nextTick();if(selectedPlan.value)show();}
async function enterClassroom(name,value){if(!await act(name,value))return;if(name==='pomodoroStart'&&(!current.value||props.model.activePlanId!==props.model.selectedPlanId))return;close();}
function restore(){if(oldOverflow!==null){document.body.style.overflow=oldOverflow;oldOverflow=null;}if(opener?.isConnected)opener.focus({preventScroll:true});}
function close(){dialog.value?.close();confirmFinish.value=false;restore();}
function backdrop(event){if(event.target!==dialog.value)return;const r=dialog.value.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)close();}
watch(selected,r=>{if(!r&&!planView.value&&dialog.value?.open)close();if(r?.phase!=='learning')confirmFinish.value=false;});
onBeforeUnmount(close);
</script>

<template>
 <section class="math-pomo" aria-label="本单元番茄列表">
  <template v-if="plans.length">
   <div class="mp-plan-heading"><span>基础计划 {{plans.length}} 个<template v-if="model.extraRounds"> · 另加 {{model.extraRounds}} 轮巩固</template></span><button v-if="rounds.length" class="mp-history" data-action="history" @click="open(current||rounds.at(-1),$event)">{{current?clock(current)+' · '+phase(current):'查看计时记录'}}</button></div>
   <nav class="mp-track mp-plans" aria-label="选择番茄学习内容">
    <button v-for="(plan,i) in plans" :key="plan.id" :data-plan="plan.id" class="mp-plan-token" :class="{selected:plan.id===model.selectedPlanId,complete:plan.status==='completed'}" :title="plan.title" :aria-label="`第 ${i+1} 个番茄：${plan.title}，${plan.status==='completed'?'目标完成':`${plan.done}/${plan.total} 项完成`}`" :aria-current="plan.id===model.selectedPlanId?'step':undefined" :disabled="working" @click="openPlan(plan,$event)"><svg viewBox="0 0 32 36" fill="none" aria-hidden="true"><path d="M16 10C4 3 0 19 6 27c4 6 16 6 20 0 6-8 2-24-10-17Z" stroke="currentColor" stroke-width="1.5"/><path d="M16 10V4m0 6-6-3m6 3 6-3" stroke="#66816a" stroke-width="1.7"/></svg><span><small>第 {{i+1}} 个 · {{plan.status==='completed'?'目标完成':plan.done?`${plan.done}/${plan.total} 项完成`:'待学习'}}</small><strong>{{plan.title}}</strong></span></button>
   </nav>

  </template>
  <div v-else class="mp-track">
   <button v-for="r in rounds" :key="r.id" :data-round="r.id" class="mp-token" :class="{running:!['finished','stopped'].includes(r.phase),paused:r.pausedAt!=null}" :aria-label="`第 ${r.index+1} 个番茄，${phase(r)}，${clock(r)}`" @click="open(r,$event)">
    <template v-if="!['finished','stopped'].includes(r.phase)">{{clock(r)}}</template>
    <template v-else><svg viewBox="0 0 32 36" fill="none" aria-hidden="true"><path d="M16 10C4 3 0 19 6 27c4 6 16 6 20 0 6-8 2-24-10-17Z" stroke="currentColor" stroke-width="1.5"/><path d="M16 10V4m0 6-6-3m6 3 6-3" stroke="#66816a" stroke-width="1.7"/></svg><span>第 {{r.index+1}} 个<small>{{r.phase==='stopped'?'未完成':'已完成'}}</small></span></template>
   </button>
   <PomodoroStartButton v-if="!current" :label="rounds.length?`第 ${rounds.length+1} 个番茄`:'开始番茄'" title="25 分钟学习" :disabled="working" @click="act('pomodoroStart')"/>
  </div>
  <div v-if="current?.phase==='ready'" class="mp-ready" role="status"><span>本轮计时完成，可以写完当前步骤再休息。</span><button data-action="start-break" :disabled="working" @click="act('pomodoroStartBreak')">开始休息 {{time(current.restTotalMs)}}</button><button data-action="skip-break" :disabled="working" @click="act('pomodoroSkipBreak')">结束本次</button></div>
  <p v-if="error" class="mp-error" role="alert">{{error}} <button data-action="retry" :disabled="working" @click="act('pomodoroRetry')">重试</button></p>
  <dialog ref="dialog" class="mp-dialog" :class="{'mp-plan-dialog':planView}" :aria-label="planView?'番茄学习计划':'番茄学习记录'" @cancel.prevent="close" @close="restore" @click="backdrop">
   <template v-if="planView && selectedPlan">
    <header class="mp-top"><div><h2>{{chapter.title}}</h2><p>{{selectedPlan.title}}</p></div><button class="mp-close" aria-label="关闭番茄计划" autofocus @click="close">×</button></header>
    <div class="mp-body"><div class="mp-workspace">
     <section class="mp-timer" aria-label="本轮计时">
      <div class="mp-timer-head"><h3>本轮学习</h3><span>{{planRound?phase(planRound):selectedPlan.status==='completed'?'目标完成':'待开始'}}</span></div>
      <div class="mp-clock" :style="{'--progress':`${ringProgress(planRound)}%`}"><div><span>{{planRound?.phase==='break'?'休息剩余':planRound&&['finished','stopped'].includes(planRound.phase)?'本轮已计时':'本轮剩余'}}</span><strong>{{planRound?clock(planRound):'25:00'}}</strong><span>计划 25 分钟</span></div></div>
      <div class="mp-actions">
       <button v-if="planEditable&&planRound.phase==='learning'&&planRound.pausedAt==null" class="mp-primary" data-action="pause" :disabled="working" @click="act('pomodoroPause')">暂停</button>
       <button v-else-if="planEditable&&planRound.phase==='learning'" class="mp-primary" data-action="resume" :disabled="working" @click="act('pomodoroResume')">继续计时</button>
       <button v-else-if="planEditable&&planRound.phase==='ready'" class="mp-primary" data-action="start-break" :disabled="working" @click="act('pomodoroStartBreak')">开始休息</button>
       <button v-else-if="planEditable&&planRound.phase==='break'" class="mp-primary" data-action="skip-break" :disabled="working" @click="act('pomodoroSkipBreak')">结束休息</button>
       <button v-else-if="!current&&selectedPlan.status!=='completed'" class="mp-primary" data-action="start" :disabled="working" @click="enterClassroom('pomodoroStart')">{{selectedPlan.continuation?'继续本计划':'开始本轮'}}</button>
       <button data-action="collapse" @click="close">收起</button>
      </div>
     </section>
   <section class="mp-plan-goal mp-report" aria-label="当前番茄目标">
    <div class="mp-plan-summary"><div><p class="mp-plan-caption">本轮目标</p><h2>{{selectedPlan.goal}}</h2></div><span class="mp-plan-progress">{{selectedPlan.done}} / {{selectedPlan.total}} 项完成</span></div>
    <nav class="mp-tasks" aria-label="本轮课堂任务"><button v-for="(task,i) in selectedPlan.tasks" :key="task.id" :data-task="task.id" :aria-current="task.id===taskId?'step':undefined" :aria-label="task.title+(task.done?'，已完成':'，待完成')" :class="{done:task.done}" :disabled="working" @click="enterClassroom('pomodoroGoTask',task.id)"><CompletionMark :done="task.done" :label="i+1"/><span>{{task.title}}<small v-if="task.priorMastery" class="mp-prior-mastery">已有掌握，略过讲解</small></span><small>{{task.minutes}} 分钟</small></button></nav>
    <div class="mp-plan-controls"><button v-if="planRound" class="mp-history" data-action="timer" @click="open(planRound,$event)">查看本轮学习记录</button><button v-if="current&&model.activePlanId&&model.activePlanId!==model.selectedPlanId" class="mp-history" :disabled="working" @click="act('pomodoroSelectPlan',model.activePlanId)">返回正在学习的番茄</button><span v-if="selectedPlan.status==='completed'" class="mp-plan-complete">本轮目标已完成</span><span v-if="selectedPlan.continuation" class="mp-carry">尚有任务待完成，继续本计划</span></div>
   </section>
    </div>
    <p v-if="error" class="mp-error" role="alert">{{error}} <button :disabled="working" @click="act('pomodoroRetry')">重试</button></p>
    </div>
   </template>
   <template v-else-if="selected">
    <header class="mp-top"><div><h2>{{chapter.title}}</h2><p>第 {{selected.index+1}} 轮计时 · {{selected.nodeTitle}}</p></div><button class="mp-close" aria-label="收起番茄详情" autofocus @click="close">×</button></header>
    <nav v-if="plans.length&&rounds.length>1" class="mp-history-rounds" aria-label="历次计时记录"><button v-for="r in rounds" :key="r.id" :data-round="r.id" :aria-current="r.id===selectedId?'true':undefined" @click="selectedId=r.id;confirmFinish=false">第 {{r.index+1}} 轮 · {{phase(r)}}</button></nav>
    <div class="mp-body"><div class="mp-workspace">
     <section class="mp-timer" aria-label="本轮计时">
      <div class="mp-timer-head"><h3>本轮学习</h3><span>{{phase(selected)}}</span></div>
      <div class="mp-clock" :style="{'--progress':`${progress}%`}"><div><span>{{selected.phase==='break'?'休息剩余':['finished','stopped'].includes(selected.phase)?'本轮已计时':'本轮剩余'}}</span><strong>{{clock(selected)}}</strong><span>计划 25 分钟</span></div></div>
      <div class="mp-actions">
       <button v-if="editable&&selected.phase==='learning'&&selected.pausedAt==null" class="mp-primary" data-action="pause" :disabled="working" @click="act('pomodoroPause')">暂停</button>
       <button v-else-if="editable&&selected.phase==='learning'" class="mp-primary" data-action="resume" :disabled="working" @click="act('pomodoroResume')">继续计时</button>
       <button v-else-if="editable&&selected.phase==='ready'" class="mp-primary" data-action="start-break" :disabled="working" @click="act('pomodoroStartBreak')">开始休息</button>
       <button v-else-if="editable&&selected.phase==='break'" class="mp-primary" data-action="skip-break" :disabled="working" @click="act('pomodoroSkipBreak')">结束休息</button>
       <button data-action="collapse" @click="close">收起</button>
      </div>
      <button v-if="editable&&selected.phase==='learning'&&!confirmFinish" class="mp-secondary" data-action="request-finish" @click="confirmFinish=true">提前结束本轮</button>
      <div v-if="editable&&selected.phase==='learning'&&confirmFinish" class="mp-confirm"><p>提前结束会保留记录，本轮标为未完成。</p><div class="mp-actions"><button data-action="cancel-finish" @click="confirmFinish=false">继续学习</button><button data-action="confirm-finish" :disabled="working" @click="act('pomodoroFinish')">确认结束</button></div></div>
      <button v-if="editable&&selected.phase==='ready'" class="mp-secondary" data-action="skip-break" :disabled="working" @click="act('pomodoroSkipBreak')">结束本次</button>
     </section>
     <section class="mp-report"><div class="mp-report-head"><h3>本轮学习记录</h3><span>{{selected.items.length}} 项记录</span></div>
      <div class="mp-metrics"><div><strong>{{time(selected.elapsedMs)}}</strong><span>番茄计时时长</span></div><div><strong data-metric="questions">{{questions.length}}</strong><span>已作答题目</span></div><div><strong data-metric="pending">{{pending}}</strong><span>待批改题目</span></div></div>
      <details v-for="item in selected.items" :key="item.id" class="mp-record"><summary><strong>{{item.title}}</strong><span>{{status(item)}}</span></summary><p>{{item.detail||'已保存学习记录'}}<template v-if="typeof item.score==='number'"> · {{item.score}} / 10</template></p></details>
      <button class="mp-return mp-primary" @click="close">返回课堂继续学习</button>
     </section>
    </div><p v-if="error" class="mp-error" role="alert">{{error}} <button :disabled="working" @click="act('pomodoroRetry')">重试</button></p></div>
   </template>
  </dialog>
 </section>
</template>

<style scoped>
