clock-link{background:white;color:#347679;font-variant-numeric:tabular-nums}.mp-carry,.mp-plan-complete{font-size:13px;color:#53685b}.mp-history-rounds{display:flex;gap:8px;overflow-x:auto;padding:12px 26px 0}.mp-history-rounds button{flex:none;background:white;color:#53685b;border:1px solid #dce5de;border-radius:8px;padding:6px 12px;font-size:12px}.mp-history-rounds button[aria-current=true]{border-color:#347679;color:#347679}.mp-plan-token:focus-visible,.mp-tasks button:focus-visible,.mp-plan-controls button:focus-visible,.mp-history:focus-visible{outline:3px solid #347679;outline-offset:-3px}
@media(max-width:700px){.mp-plan-heading{gap:8px;font-size:12px}.mp-plan-token{flex-basis:205px;padding:10px 12px}.mp-plan-goal{padding:14px 12px}.mp-plan-summary{align-items:flex-start;flex-direction:column;gap:6px}.mp-plan-summary h2{font-size:15px}.mp-tasks{display:grid;grid-template-columns:1fr}.mp-tasks button{width:100%;min-width:0}.mp-tasks button>span:nth-child(2){flex:1;overflow-wrap:anywhere}.mp-plan-controls{gap:8px}.mp-begin{width:100%}.mp-history-rounds{padding:10px 16px 0}}
