lay:grid;place-items:center;background:transparent;border:0;border-radius:10px;width:44px;height:44px;padding:0;font-size:28px!important;line-height:1;color:#626e6c;flex:none}.mp-body{padding:16px 24px 24px}.mp-workspace{display:grid;grid-template-columns:290px minmax(0,1fr);gap:22px;align-items:start}.mp-timer,.mp-report{background:white;border:1px solid #dce5e2;border-radius:18px;padding:22px;min-width:0}.mp-timer{text-align:center}.mp-timer-head,.mp-report-head{display:flex;justify-content:space-between;align-items:center;gap:12px}.mp-timer-head span,.mp-report-head span{font-size:13px;color:#626e6c}.mp-dialog h3{font-size:16px;margin:0;line-height:1.6}.mp-clock{width:226px;height:226px;border-radius:50%;margin:16px auto;background:conic-gradient(#347679 var(--progress),#e7f0ed 0);padding:6px;box-sizing:border-box}.mp-clock>div{display:flex;align-items:center;justify-content:center;flex-direction:column;height:100%;border-radius:50%;background:white}.mp-clock strong{font-size:51px;font-weight:300;line-height:1.4;font-variant-numeric:tabular-nums;letter-spacing:-2px}.mp-clock span{font-size:12px;color:#626e6c}.mp-actions{display:flex;gap:8px;margin:15px 0}.mp-actions button{flex:1;border:1px solid #dce5e2;border-radius:10px;padding:10px 12px;background:white;color:#253b3d;font-size:14px}.math-pomo .mp-primary{background:#347679;color:white;border-color:#347679}.mp-confirm p{font-size:13px;line-height:1.8;margin:0 0 8px;color:#626e6c}.mp-secondary{border:0;background:transparent;color:#626e6c;font-size:13px!important;text-decoration:underline}.mp-confirm{margin-top:12px;text-align:left}.mp-report{padding:24px}.mp-metrics{margin-top:16px;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;padding:6px 0 20px;margin-bottom:8px}.mp-metrics strong{display:block;font-size:27px;font-weight:500;font-variant-numeric:tabular-nums}.mp-metrics span{display:block;font-size:12px;color:#626e6c;margin-top:7px;line-height:1.8}.mp-record{border-bottom:1px solid #dce5